**PR Title:** `feat(sync): eager recursive sync for full offline availability`
**Motivation:** Recursively download all parent manifests and payload blocks during sync to ensure full graph history is immediately available offline.

```rust
pub async fn synchronize_graph(&mut self, remote_head: ManifestId) -> Result<(), SyncError> {
    let mut queue = VecDeque::from([remote_head]);
    while let Some(manifest_id) = queue.pop_front() {
        let manifest = self.download_and_commit_manifest(&manifest_id).await?;
        for parent in manifest.parents() {
            queue.push_back(parent);
        }
        for block in manifest.referenced_blocks() {
            self.download_and_store_payload(&block).await?;
        }
    }
    Ok(())
}
```

