pub fn parse_external_id(input: &str) -> Result<Address, AksharaError> {
    let cid = Cid::from_str(input)
        .map_err(|_| AksharaError::Integrity(IntegrityError::MalformedId))?;

    if cid.version() == cid::Version::V1 || cid.version() == cid::Version::V0 {
        Ok(Address::from(cid))
